// === Tab: mySketch ===
// Attractor_16.0

let N = 4000 ; 
let S = 0.02 ; let G = 0.012 ; let H = 0.1 ; let R = 300 ; let Q = 10 ;

let X = [N] ; let Y = [N] ; let Z = [N] ;
let L ; let dX ; let dY ; let dZ ; let P ; let U ;
let I ; let NX ; let NY ; let NZ ; let KN ;

function setup(){

  createCanvas(1000,750) ; noSmooth() ; background(0) ;
	colorMode(HSB) ;
  for ( I = 0 ; I < N ; I++ ){
    X[I] = random(+10,+90) ;
    Y[I] = random(-90,+90) ;
    Z[I] = random(+10,+90) ;
  }
  KN = N ;

}// setup()

function draw(){
  if ( KN == N ){ fill(0,0,0,.1) ; noStroke() ; rect(-1,-1,1001,751) ; fill(255) ; }
  /*line(50,400,550,400) ; line(550,400,540,390) ; line(550,400,540,410) ; text("X",560,405) ;
  line(300,50,300,550) ; line(300,50,290,60) ; line(300,50,310,60) ; text("Z",295,40) ;
  line(450,250,150,550) ; line(150,550,150,535) ; line(150,550,165,550) ; text("Y",130,570) ;*/
  translate(0, 200) ;

  for ( I = 0 ; I < KN ; I++ ){
    L = sqrt(pow(X[I],2)+pow(Y[I],2)) ;
    P = (atan((L-R)/Z[I])+(PI/2))/PI ;
    U = abs(Y[I])/L ;
    dX = (-Z[I]*H*P*U*X[I]/L) + (L*G*X[I]/L) + (-Y[I]*S) + (Q*X[I]/pow(L,3)) ; 
    dY = (-Z[I]*H*P*U*Y[I]/L) + (L*G*Y[I]/L) + (+X[I]*S) + (Q*Y[I]/pow(L,3)) ; 
    dZ = ((L-R)*H*P*U) ;
    NX = X[I] + dX ; NY = Y[I] + dY ; NZ = Z[I] + dZ ;
		//stroke(I/KN*360, 80, 100) ; // random colors
		stroke(U*360%360, 80, 100) ;  // patterned colors
    line(X[I]-(Y[I]/2)+500,-Z[I]+(Y[I]/2)+400,NX-(NY/2)+500,-NZ+(NY/2)+400) ;
    X[I] = NX ; Y[I] = NY ; Z[I] = NZ ;    

  }// I

}// draw()

function mousePressed(){

  background(0) ;
  if ( KN != N ){
    for ( I = 1 ; I < N ; I++ ){
      X[I] = X[0] + random(-10,+10) ;
      Y[I] = Y[0] + random(-10,+10) ;
      Z[I] = Z[0] + random(-10,+10) ;
    }
    KN = N ;
  }else{ KN = 1 ; }

}// mousePressed()

